        private int GetTypeSize(ExprType type)
        {
            switch (type)
            {
                case ExprType.Char:
                case ExprType.UnsignedChar:
                case ExprType.Bool:
                    return 1;
                case ExprType.Short:
                case ExprType.UnsignedShort:
                    return 2;
                case ExprType.Int:
                case ExprType.UnsignedInt:
                case ExprType.Float:
                    return 4;
                case ExprType.Long:
                case ExprType.UnsignedLong:
                case ExprType.LongLong:
                case ExprType.UnsignedLongLong:
                case ExprType.Double:
                    return 8;

                case ExprType.CharPtr: case ExprType.ShortPtr:
                case ExprType.IntPtr: case ExprType.LongPtr:
                case ExprType.FloatPtr: case ExprType.DoublePtr:
                case ExprType.VoidPtr:
                    return 4;

                case ExprType.Struct:
                    return 4; // opaque struct — use GetTypeSizeFromString for actual size

                default:
                    return 4;
            }
        }

        /// <summary>
        /// Maps C ExprType to (byteSize, isFloat, isDouble) for use with ExpressionManager.
        /// </summary>
        private static (int byteSize, bool isFloat, bool isDouble) TypeInfo(ExprType type)
        {
            switch (type)
            {
                case ExprType.Char:
                case ExprType.UnsignedChar:
                case ExprType.Bool:
                    return (1, false, false);
                case ExprType.Short:
                case ExprType.UnsignedShort:
                    return (2, false, false);
                case ExprType.Int:
                case ExprType.UnsignedInt:
                    return (4, false, false);
                case ExprType.Float:
                    return (4, true, false);
                case ExprType.Long:
                case ExprType.UnsignedLong:
                case ExprType.LongLong:
                case ExprType.UnsignedLongLong:
                    return (8, false, false);
                case ExprType.Double:
                    return (8, false, true);
                case ExprType.CharPtr:
                case ExprType.ShortPtr:
                case ExprType.IntPtr:
                case ExprType.LongPtr:
                case ExprType.FloatPtr:
                case ExprType.DoublePtr:
                case ExprType.VoidPtr:
                    return (4, false, false);
                case ExprType.Struct:
                    return (4, false, false);
                default:
                    return (4, false, false);
            }
        }

        /// <summary>
        /// Get the byte size of a type by its string name, resolving struct/union definitions.
        /// </summary>
        private int GetTypeSizeFromString(string typeName)
        {
            if (string.IsNullOrEmpty(typeName)) return 4;
            string origName = typeName;
            typeName = typeName.ToLower().Trim();
            typeName = typeName.Replace("const", "").Replace("volatile", "").Replace("restrict", "").Replace("extern", "").Replace("static", "").Trim();
            while (typeName.Contains("  ")) typeName = typeName.Replace("  ", " ");

            // Struct type: look up actual size
            if (typeName.StartsWith("struct "))
            {
                string structName = typeName.Substring(7).Trim();
                if (structs.TryGetValue(structName, out var sd)) return sd.Size;
                foreach (var kvp in structs)
                    if (kvp.Key.ToLower() == structName) return kvp.Value.Size;
                return 4; // fallback for forward-declared struct
            }
            if (typeName.StartsWith("union "))
            {
                string unionName = typeName.Substring(6).Trim();
                if (unions.TryGetValue(unionName, out var ud)) return ud.Size;
                foreach (var kvp in unions)
                    if (kvp.Key.ToLower() == unionName) return kvp.Value.Size;
                return 4;
            }

            // Resolve typedef alias → recurse
            if (typeAliases.TryGetValue(typeName, out var resolved))
            {
                if (resolved == "struct" || resolved == "union")
                {
                    // The typedef name IS the struct name
                    if (structs.TryGetValue(typeName, out var sd)) return sd.Size;
                    foreach (var kvp in structs)
                        if (kvp.Key.ToLower() == typeName) return kvp.Value.Size;
                    if (unions.TryGetValue(typeName, out var ud)) return ud.Size;
                    foreach (var kvp in unions)
                        if (kvp.Key.ToLower() == typeName) return kvp.Value.Size;
                    return 4;
                }
                // Recurse for all typedef resolutions (handles array types, pointer typedefs, etc.)
                return GetTypeSizeFromString(resolved);
            }

            // Pointer types are always 4 bytes
            if (typeName.Contains('*')) return 4;

            // Handle array types — extract dimensions from type string
            // e.g., "unsigned char[4][4]" → element size 1 * 4 * 4 = 16
            string baseType = typeName;
            int arrayMultiplier = 1;
            int bracketStart = typeName.IndexOf('[');
            while (bracketStart >= 0)
            {
                int bracketEnd = typeName.IndexOf(']', bracketStart);
                if (bracketEnd < 0) break;
                string dimStr = typeName.Substring(bracketStart + 1, bracketEnd - bracketStart - 1).Trim();
                if (int.TryParse(dimStr, out int dimVal) && dimVal > 0)
                    arrayMultiplier *= dimVal;
                baseType = typeName.Substring(0, bracketStart).Trim();
                bracketStart = typeName.IndexOf('[', bracketEnd + 1);
            }
            if (arrayMultiplier != 1)
                return GetTypeSizeFromString(baseType) * arrayMultiplier;

            return GetTypeSize(StringToExprType(typeName));
        }

        /// 从类型字符串中提取数组维度，如 "unsigned char[4][4]" → [4, 4]
        /// 返回 null 如果没有数组维度
        private static List<int?>? ExtractArrayDimensions(string typeName)
        {
            if (string.IsNullOrEmpty(typeName)) return null;
            typeName = typeName.Trim();
            List<int?> dims = new List<int?>();
            int bracketStart = typeName.IndexOf('[');
            while (bracketStart >= 0)
            {
                int bracketEnd = typeName.IndexOf(']', bracketStart);
                if (bracketEnd < 0) break;
                string dimStr = typeName.Substring(bracketStart + 1, bracketEnd - bracketStart - 1).Trim();
                if (int.TryParse(dimStr, out int dimVal) && dimVal > 0)
                    dims.Add(dimVal);
                else
                    dims.Add(null);
                bracketStart = typeName.IndexOf('[', bracketEnd + 1);
            }
            return dims.Count > 0 ? dims : null;
        }

        /// 剥离类型字符串中的数组维度，如 "unsigned char[4][4]" → "unsigned char"
        private static string StripArrayDimensions(string typeName)
        {
            if (string.IsNullOrEmpty(typeName)) return typeName;
            int bracketStart = typeName.IndexOf('[');
            return bracketStart >= 0 ? typeName.Substring(0, bracketStart).Trim() : typeName;
        }

        private static OpCode GetLoadOpForExprType(ExprType type)
        {
            switch (type)
            {
                case ExprType.Char: case ExprType.UnsignedChar:
                    return OpCode.MOVEB;
                case ExprType.Short: case ExprType.UnsignedShort:
                    return OpCode.MOVEH;
                case ExprType.Float: return OpCode.MOVEF;
                case ExprType.Double: return OpCode.MOVED;
                default: return OpCode.MOVE;
            }
        }

        private static OpCode GetStoreOpForExprType(ExprType type)
        {
            switch (type)
            {
                case ExprType.Char: case ExprType.UnsignedChar:
                    return OpCode.MOVEB;
                case ExprType.Short: case ExprType.UnsignedShort:
                    return OpCode.MOVEH;
                case ExprType.Float: return OpCode.MOVEF;
                case ExprType.Double: return OpCode.MOVED;
                default: return OpCode.MOVE;
            }
        }

        /// <summary>
        /// 加载有符号小类型后发射 SEXTB/SEXTH 进行符号扩展 (v1.66.5)
        /// </summary>
        private void EmitSignExtendIfSigned(ExprType type)
        {
            if (type == ExprType.Char)
                instructions.Add(new Instruction(OpCode.SEXTB, new List<Operand> { Reg(0), Reg(0) }));
            else if (type == ExprType.Short)
                instructions.Add(new Instruction(OpCode.SEXTH, new List<Operand> { Reg(0), Reg(0) }));
        }

        /// <summary>
        /// 根据数据类型获取加载指令
        /// </summary>
        private OpCode GetLoadInstruction(ExprType type)
        {
            if (type == ExprType.Long || type == ExprType.UnsignedLong ||
                type == ExprType.LongLong || type == ExprType.UnsignedLongLong)
                return VMLPlugins.CompilerOptionsContext.Current.Int64Mode == VMLPlugins.Int64Mode.Hard ? OpCode.MOVEL : OpCode.MOVE;
            var (s, f, d) = TypeInfo(type);
            return ExpressionManager.SelectLoadOp(s, f, d);
        }

        private OpCode GetStoreInstruction(ExprType type)
        {
            if (type == ExprType.Long || type == ExprType.UnsignedLong ||
                type == ExprType.LongLong || type == ExprType.UnsignedLongLong)
                return VMLPlugins.CompilerOptionsContext.Current.Int64Mode == VMLPlugins.Int64Mode.Hard ? OpCode.MOVEL : OpCode.MOVE;
            var (s, f, d) = TypeInfo(type);
            return ExpressionManager.SelectStoreOp(s, f, d);
        }

        /// <summary>
        /// 发射从 fromType 到 toType 的类型转换指令 (在 R0 上操作)
        /// </summary>
        private void EmitTypeConversion(ExprType fromType, ExprType toType)
        {
            if (fromType == toType) return;

            bool fromFloat = fromType == ExprType.Float, fromDouble = fromType == ExprType.Double;
            bool toFloat = toType == ExprType.Float, toDouble = toType == ExprType.Double;
            int fromSize = GetTypeSize(fromType), toSize = GetTypeSize(toType);
            bool fromLong = fromType == ExprType.Long || fromType == ExprType.UnsignedLong
                            || fromType == ExprType.LongLong || fromType == ExprType.UnsignedLongLong;
            bool toLong = toType == ExprType.Long || toType == ExprType.UnsignedLong
                          || toType == ExprType.LongLong || toType == ExprType.UnsignedLongLong;

            var convOp = ExpressionManager.SelectConversionOp(fromSize, fromFloat, fromDouble,
                                                               toSize, toFloat, toDouble,
                                                               fromLong, toLong);
            if (convOp != null)
                instructions.Add(new Instruction(convOp.Value, new List<Operand> {
                    new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 0) }));
        }

        /// <summary>
        /// 根据数据类型获取移动指令
        /// </summary>
        private OpCode GetMoveInstruction(ExprType type)
        {
            if (type == ExprType.Long || type == ExprType.UnsignedLong ||
                type == ExprType.LongLong || type == ExprType.UnsignedLongLong)
                return VMLPlugins.CompilerOptionsContext.Current.Int64Mode == VMLPlugins.Int64Mode.Hard ? OpCode.MOVEL : OpCode.MOVE;
            var (s, f, d) = TypeInfo(type);
            return ExpressionManager.SelectMoveOp(s, f, d);
        }

        /// <summary>
        /// 根据数据类型获取压栈指令
