        /// <summary>
        /// 根据数据类型获取算术运算指令
        /// </summary>
        private OpCode GetArithmeticInstruction(string op, ExprType type)
        {
            if (type == ExprType.Long || type == ExprType.UnsignedLong ||
                type == ExprType.LongLong || type == ExprType.UnsignedLongLong)
            {
                if (VMLPlugins.CompilerOptionsContext.Current.Int64Mode == VMLPlugins.Int64Mode.Hard)
                {
                    return op switch
                    {
                        "+" => OpCode.ADDL,
                        "-" => OpCode.SUBL,
                        "*" => OpCode.MULL,
                        "/" => OpCode.DIVL,
                        "%" => OpCode.MODL,
                        _ => OpCode.ADDL
                    };
                }
                return op switch
                {
                    "+" => OpCode.ADD,
                    "-" => OpCode.SUB,
                    "*" => OpCode.MUL,
                    "/" => OpCode.DIV,
                    "%" => OpCode.MOD,
                    _ => OpCode.ADD
                };
            }
            var (_, f, d) = TypeInfo(type);
            return ExpressionManager.SelectArithmeticOp(op, f, d);
        }

        /// <summary>
        /// 根据数据类型获取比较指令
        /// </summary>
        private OpCode GetCompareInstruction(ExprType type)
        {
            if ((type == ExprType.Long || type == ExprType.UnsignedLong ||
                 type == ExprType.LongLong || type == ExprType.UnsignedLongLong)
                && VMLPlugins.CompilerOptionsContext.Current.Int64Mode == VMLPlugins.Int64Mode.Hard)
                return OpCode.CMPL;
            var (_, f, d) = TypeInfo(type);
            return ExpressionManager.SelectCompareOp(f, d);
        }

        /// <summary>
        /// 生成比较操作
        /// </summary>
        private void GenerateComparison(string op, ExprType exprType)
        {
            string lbl = GenerateLabel();
            string end = GenerateLabel();

            // 使用正确的比较指令
            var cmpOp = GetCompareInstruction(exprType);
            AddRR(cmpOp, 1, 0);

            // 根据操作符选择跳转指令（必须在CMP后立即使用，否则标志位会变）
            OpCode jumpOp = op switch
            {
                "<" => OpCode.JL,
                "<=" => OpCode.JLE,
                ">" => OpCode.JG,
                ">=" => OpCode.JGE,
                "==" => OpCode.JE,
                "!=" => OpCode.JNE,
                _ => OpCode.JMP
            };

            instructions.Add(new Instruction(jumpOp, new List<Operand> { new Operand(OperandType.LABEL, lbl) }));
            // 条件不满足时结果为0
            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, 0) }));
            instructions.Add(new Instruction(OpCode.JMP, new List<Operand> { new Operand(OperandType.LABEL, end) }));

            // 条件满足时结果为1
            labels[lbl] = instructions.Count;
            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, 1) }));
            labels[end] = instructions.Count;
        }

        /// <summary>
        /// 检查是否是指针类型
        /// </summary>
        private bool IsPointerType(ExprType type)
        {
            return type == ExprType.CharPtr ||
                   type == ExprType.ShortPtr ||
                   type == ExprType.IntPtr ||
                   type == ExprType.LongPtr ||
                   type == ExprType.FloatPtr ||
                   type == ExprType.DoublePtr ||
                   type == ExprType.VoidPtr;
        }

        private static bool IsInt64HardLong(ExprType type)
            => (type == ExprType.Long || type == ExprType.UnsignedLong ||
                type == ExprType.LongLong || type == ExprType.UnsignedLongLong)
               && VMLPlugins.CompilerOptionsContext.Current.Int64Mode == VMLPlugins.Int64Mode.Hard;

        private bool IsIntegerType(ExprType type)
        {
            return type == ExprType.Char || type == ExprType.UnsignedChar ||
                   type == ExprType.Short || type == ExprType.UnsignedShort ||
                   type == ExprType.Int || type == ExprType.UnsignedInt ||
                   type == ExprType.Long || type == ExprType.UnsignedLong ||
                   type == ExprType.LongLong || type == ExprType.UnsignedLongLong;
        }

        /// <summary>
        /// 查找变量声明
        /// </summary>
        private VariableDecl? FindVariableDeclaration(string variableName)
        {
            // 在全局变量声明中查找
            foreach (var varDecl in ast.Variables)
            {
                if (varDecl.Name == variableName)
                {
                    return varDecl;
                }
            }

            // 在当前函数的局部变量中查找
            if (localArrayDimensions.TryGetValue(variableName, out var dims))
            {
                var decl = new VariableDecl(variableName, "int", null, true);
                decl.Dimensions = dims;
                return decl;
            }

            return null;
        }

        /// <summary>
        /// 检查标识符是否为已知变量（非函数）。用于区分间接调用和隐式函数声明。
        /// </summary>
        public bool IsKnownVariable(string name)
        {
            return variables.ContainsKey(name) ||
                   variableTypes.ContainsKey(name) ||
                   staticLocals.ContainsKey(name) ||
                   dataSection.ContainsKey(name) ||
                   enumValues.ContainsKey(name);
        }

        /// <summary>
        /// 获取指针指向的类型大小（用于指针算术）
        /// </summary>
        private int GetPointedTypeSize(ExprType pointerType)
        {
            switch (pointerType)
            {
                case ExprType.CharPtr:
                    return 1; // char
                case ExprType.ShortPtr:
                    return 2; // short
                case ExprType.IntPtr:
                case ExprType.FloatPtr:
                case ExprType.VoidPtr:
                    return 4; // int, float, void*
                case ExprType.LongPtr:
                case ExprType.DoublePtr:
                    return 8; // long, double
                default:
                    return 4; // 默认int大小
            }
        }

        private string GenerateLabel()
        {
            // `L_` 前缀不能省：`L0`–`L7` 会被汇编器当成**长整数寄存器**，跳转静默失效（v0.96.192）
            var label = $"L_{labelCounter}";
            labelCounter++;
            return label;
        }
    }
